      ,scene_id
      ,scene_name
      ,layer_id
      ,layer_name
      ,experiment_id
      ,experiment_name
      ,start_datetime
      ,end_datetime
from (
     select group_id    as exp_group_id
           ,group_name  as exp_group_name
           ,project_id
           ,project_name
           ,scene_id
           ,scene_name
           ,layer_id
           ,layer_name
           ,experiment_id
           ,experiment_name
           ,if(start_time > 0, from_unixtime(cast(start_time/1000 as bigint), 'yyyy-MM-dd HH:mm:ss'), null) as start_datetime
           ,if(end_time > 0, from_unixtime(cast(end_time/1000 as bigint), 'yyyy-MM-dd HH:mm:ss'), null) as end_datetime
           ,row_number()over(partition by group_id order by end_time desc) as rn
     from abtest.shopee_experiment_admin_db__group_dimension_tab__reg_continuous_s0_live
) t
where rn = 1
;

