insert overwrite table ${schema}.dim_sr_data_warehouse_abtest_group partition(local_date = ${local_date})
select t1.exp_group_id
      ,t1.experiment_id
      ,t1.scene_id
      ,t1.layer_id
      ,t1.project_name
      ,t1.start_datetime
      ,t1.end_datetime

      ,t2.exp_algo_tags

       -- rcmd_whitelist
      ,case
         when t1.project_name = 'MKP RCMD' or t3.is_rcmd_whitelist = 1 or t4.is_rcmd_whitelist = 1 or t5.is_rcmd_whitelist = 1 then 1
         else 0
       end as is_rcmd_whitelist

       -- search_whitelist
      ,case
         when t3.is_search_whitelist = 1 or t4.is_search_whitelist = 1 or t5.is_search_whitelist = 1 then 1
         else 0
       end as is_search_whitelist

       -- rcmd_search_whitelist
      ,case
         when t1.project_name = 'MKP RCMD' or t3.is_rcmd_whitelist = 1 or t4.is_rcmd_whitelist = 1 or t5.is_rcmd_whitelist = 1 then 1 -- rcmd
         when t3.is_search_whitelist = 1 or t4.is_search_whitelist = 1 or t5.is_search_whitelist = 1 then 1 -- search
         else 0
       end as is_rcmd_search_whitelist

       -- homepage_whitelist
      ,case
         when t3.is_homepage_whitelist = 1 or t4.is_homepage_whitelist = 1 or t5.is_homepage_whitelist = 1 then 1
         else 0
       end as is_homepage_whitelist

       -- homepage_other_whitelist
      ,case
         when t3.is_homepage_other_whitelist = 1 or t4.is_homepage_other_whitelist = 1 or t5.is_homepage_other_whitelist = 1 then 1
         else 0
       end as is_homepage_other_whitelist

       -- whitelist filter condition for a few downstream rcmd abtest tables
      ,case
         when t1.project_name = 'MKP RCMD' or t3.is_rcmd_whitelist = 1 then 1
         else 0
       end as is_rcmd_scene_whitelist

       -- ads_whitelist
      ,case
         when t3.is_ads_whitelist = 1 or t4.is_ads_whitelist = 1 or t5.is_ads_whitelist = 1 then 1
         else 0
       end as is_ads_whitelist

      ,t1.project_id
      ,t1.scene_name
      ,t1.layer_name
      ,t1.experiment_name
      ,t1.exp_group_name
from abtest_group_${grass_region_without_quote} t1
left join abtest_experiment_${grass_region_without_quote} t2 on t1.experiment_id = t2.experiment_id
left join abtest_scene_whitelist_${grass_region_without_quote} t3 on t1.scene_id = t3.scene_id
left join abtest_layer_exp_whitelist_${grass_region_without_quote} t4 on t1.layer_id = t4.layer_id
left join abtest_exp_whitelist_${grass_region_without_quote} t5 on t1.experiment_id = t5.experiment_id
;
